import hashlib

documents = [
    "Machine learning models require large amounts of training data.",
    "Machine learning models require large amounts of training data.",
    "Machine learning models require a large amount of training data.",
    "Databases store structured records in tables.",
]

def normalized_hash(text):
    # hash normalized text to catch exact duplicates
    normalized = text.lower().strip()
    return hashlib.sha256(normalized.encode()).hexdigest()

def word_overlap_ratio(a, b):
    # measure word overlap to catch near duplicates
    words_a, words_b = set(a.lower().split()), set(b.lower().split())
    return len(words_a & words_b) / len(words_a | words_b)

seen_hashes = {}
for i, doc in enumerate(documents):
    h = normalized_hash(doc)
    if h in seen_hashes:
        print(f"Document {i} is an exact duplicate of document {seen_hashes[h]}")
    else:
        seen_hashes[h] = i

print("\nNear duplicate check:")
for i in range(len(documents)):
    for j in range(i + 1, len(documents)):
        ratio = word_overlap_ratio(documents[i], documents[j])
        if ratio > 0.7:
            print(f"  Documents {i} and {j} are near duplicates, overlap={ratio:.2f}")
